def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    average_expected_volatility = (v1 + v2) / 2
    return {
        "value": average_expected_volatility,
        "trace": {
            "v1": v1,
            "v2": v2,
            "average_expected_volatility": average_expected_volatility,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
